text:
Skrócony plan wykładu
W trakcie wykładu poruszymy następujące zagadnienia:

A) Przestrzeń probabilistyczna: aksjomatyka rachunku prawdopodobieństwa, prawdopodobieństwo warunkowe, prawdopodobieństwo całkowite, wzór Bayesa, niezależność zdarzeń;
B) elementy losowe: zmienne losowe, wektory losowe, niezależne zmienne losowe;
C) rozkłady prawdopodobieństwa: rozkłady zmiennych losowych, dystrybuanty, rozkłady dyskretne i absolutnie ciągłe;
D) parametry rozkładów: wartość oczekiwana, wariancja, kowariancja;
E) twierdzenia graniczne: prawo wielkich liczb, centralne twierdzenie graniczne.

Podstawowa literatura do wykładu:

Mitzenmacher, M, Upfal E. (2017) Probability and Computing, Cambridge University Press
Isaac, R. (2000). The Pleasures of Probability. Springer.
Blitzstein, J. K, Hwang, J, (2019) Introduction to Probability, Taylor & Francis
Grimmett, G, Stirzaker, D. (2001) Probability and Random Processes, Oxford University Press

Efekty kształcenia
Po wykładzie student:

Wymienia i definiuje podstawowe obiekty teorii prawdopodobieństwa (A, B, C, D );
Podaje związki między podstawowymi obiektami teorii prawdopodobieństwa (A, B, C, D );
Wykorzystuje narzędzia teorii prawdopodobieństwa do opisu zmiennych losowych w terminach ich rozkładu i ich parametrów (B, C, D);
Formułuje twierdzenia graniczne (D);
Stosuje twierdzenia graniczne do analizy ciągów zmiennych losowych (B, E);

Sposób weryfikacji efektów kształcenia
Na zaliczenie składać się będą:

Aktywność na ćwiczeniach;
Kartkówki na każdych ćwiczeniach;
Dwa kolokwia;

Warunkiem zaliczenia przedmiotu

Uzyskanie 50% punktów za zadania stanowiące bieżącą weryfikację efektów kształcenia;
Uzyskanie pozytywnej oceny z egzaminu stanowiącego końcową weryfikację efektów kształcenia.

1.1 Boarding samolotu
Sztuczna inteligencja i analiza danych opierają się na bardzo prostej zasadzie: na podstawie ograniczonej liczby przykładów (danych treningowych) chcemy wyciągać wnioski o zjawiskach, których nie widzimy w całości. Dane treningowe zawierają szum, błędy pomiarowe, przypadkowe odchylenia, braki oraz zależności, których często nie potrafimy bezpośrednio zaobserwować. Dlatego analiza danych nie jest jedynie rachunkiem na tabelach liczb. Jest próbą rozumowania w warunkach niepewności. Rachunek prawdopodobieństwa dostarcza języka, w którym tę niepewność można precyzyjnie opisać.
Mimo że poniższe notatki stanowią materiał do standardowego kursu z teorii prawdopodobieństwa postaramy się dobrze umotywować główny kierunek wykładu. Zaczniemy od przykładu pokazującego że losowe zaburzenia nie są problemem, a narzędziem, które można wykorzystać na swoją korzyść.
Zaczniemy od zagadnienia wpuszczania pasażerów na pokład samolotu. Poniższa symulacja porównuje trzy kolejności wpuszczania pasażerów: uporządkowani zgodnie z numerami siedzeń, losowo oraz metodą z pracy Steffen (2008).
Pokaż kod
html`&lt;style&gt;
.boarding-controls { display:flex; gap:.6rem; align-items:center; flex-wrap:wrap; margin:.5rem 0 1rem; }
.boarding-controls button { padding:.42rem .8rem; border:1px solid #9aa4b2; border-radius:.4rem; background:var(--bs-body-bg,#fff); color:var(--bs-body-color,#222); cursor:pointer; }
.boarding-controls button.primary { background:#2563eb; border-color:#2563eb; color:white; }
.boarding-controls label { display:flex; align-items:center; gap:.45rem; margin-left:.4rem; }
.boarding-grid { display:grid; grid-template-columns:repeat(3,minmax(220px,1fr)); gap:1rem; }
.boarding-panel { min-width:0; }
.boarding-panel h3 { margin:.1rem 0; font-size:1rem; text-align:center; }
.boarding-status { text-align:center; color:#667085; min-height:1.5rem; font-variant-numeric:tabular-nums; }
.boarding-panel svg { width:100%; height:auto; display:block; }
.boarding-legend { display:flex; justify-content:center; gap:1rem; flex-wrap:wrap; margin-top:.8rem; color:#667085; font-size:.9rem; }
.boarding-key { display:inline-flex; align-items:center; gap:.35rem; }
.boarding-dot { width:.72rem; height:.72rem; border-radius:50%; display:inline-block; }
@media (max-width:780px) { .boarding-grid { grid-template-columns:1fr; } .boarding-panel svg { max-height:620px; } }
&lt;/style&gt;`
Pokaż kod
boarding = {
  const ROWS = 24;
  const COLS = ["A", "B", "C", "D", "E", "F"];
  const AISLE_AFTER = 2;
  const COLORS = {
    empty: "#d8dee8", seated: "#22c55e", walking: "#2563eb",
    stowing: "#f59e0b", waiting: "#ef4444", aisle: "#eef2f7",
    outline: "#7b8798", text: "#344054"
  };

  // Powtarzalny generator liczb pseudolosowych.
  function rng(seed) {
    let x = seed &gt;&gt;&gt; 0;
    return () =&gt; ((x = (1664525 * x + 1013904223) &gt;&gt;&gt; 0) / 4294967296);
  }
  function shuffled(xs, random) {
    const a = xs.slice();
    for (let i = a.length - 1; i &gt; 0; --i) {
      const j = Math.floor(random() * (i + 1));
      [a[i], a[j]] = [a[j], a[i]];
    }
    return a;
  }
  function passengers() {
    return Array.from({length: ROWS}, (_, r) =&gt;
      COLS.map((seat, c) =&gt; ({id: `${r + 1}${seat}`, row:r, col:c, seat}))
    ).flat();
  }
  function orderFor(method, random) {
    const all = passengers();
    if (method === "random") return shuffled(all, random);
    if (method === "back") {
      const ans = [];
      for (let r = ROWS - 1; r &gt;= 0; --r)
        ans.push(...shuffled(all.filter(p =&gt; p.row === r), random));
      return ans;
    }
    // Metoda Steffena: najpierw okna, potem środek, na końcu przejście;
    // w każdej grupie naprzemienne rzędy od tyłu i obie strony kabiny.
    const ans = [];
    for (const pair of [[0,5],[1,4],[2,3]]) {
      for (const parity of [1,0]) {
        for (let r = ROWS - 1; r &gt;= 0; --r) {
          if (r % 2 === parity)
            for (const c of pair) ans.push(all.find(p =&gt; p.row === r && p.col === c));
        }
      }
    }
    return ans;
  }
  function makeSim(method, seed) {
    const random = rng(seed);
    return {
      method, random, queue:orderFor(method, random), active:[], seated:new Set(),
      time:0, done:false, simultaneous:0
    };
  }
  function seatDelay(p, seated) {
    // 3 jednostki na bagaż oraz dodatkowy czas, gdy trzeba przepuścić
    // osobę siedzącą bliżej przejścia.
    let delay = 3;
    if (p.col === 0) delay += (seated.has(`${p.row}-2`) ? 2 : 0) + (seated.has(`${p.row}-1`) ? 2 : 0);
    if (p.col === 1) delay += seated.has(`${p.row}-2`) ? 2 : 0;
    if (p.col === 5) delay += (seated.has(`${p.row}-3`) ? 2 : 0) + (seated.has(`${p.row}-4`) ? 2 : 0);
    if (p.col === 4) delay += seated.has(`${p.row}-3`) ? 2 : 0;
    return delay;
  }
  function step(sim) {
    if (sim.done) return;
    sim.time++;

    const blocked = new Set(sim.active.filter(p =&gt; p.state === "stowing").map(p =&gt; p.pos));
    const occupied = new Set(sim.active.filter(p =&gt; p.state !== "seated").map(p =&gt; p.pos));

    // Aktualizujemy od najdalszego pasażera, aby nikt nie przeszedł przez inną osobę.
    const moving = sim.active.slice().sort((a,b) =&gt; b.pos - a.pos);
    for (const p of moving) {
      if (p.state === "stowing") {
        p.wait--;
        if (p.wait &lt;= 0) {
          p.state = "seated";
          sim.seated.add(`${p.row}-${p.col}`);
          occupied.delete(p.pos);
        }
      } else if (p.state === "walking") {
        if (p.pos === p.row) {
          p.state = "stowing";
          p.wait = seatDelay(p, sim.seated);
        } else {
          const next = p.pos + 1;
          if (!occupied.has(next) && !blocked.has(next)) {
            occupied.delete(p.pos); p.pos = next; occupied.add(p.pos);
          }
        }
      }
    }
    sim.active = sim.active.filter(p =&gt; p.state !== "seated");

    // Jedna osoba może wejść w każdej jednostce czasu, jeśli początek przejścia jest wolny.
    if (sim.queue.length && !occupied.has(-1) && !occupied.has(0)) {
      const p = sim.queue.shift();
      sim.active.push({...p, pos:-1, state:"walking", wait:0});
    }
    sim.done = sim.queue.length === 0 && sim.active.length === 0;
  }

  const methods = [
    {id:"back", label:"Od tyłu do przodu"},
    {id:"random", label:"Kolejność losowa"},
    {id:"steffen", label:"Metoda Steffena"}
  ];
  const root = html`&lt;div&gt;
    &lt;div class="boarding-controls"&gt;
      &lt;button class="primary" data-action="start"&gt;▶ Start&lt;/button&gt;
      &lt;button data-action="pause"&gt;Ⅱ Pauza&lt;/button&gt;
      &lt;button data-action="reset"&gt;↺ Od początku&lt;/button&gt;
      &lt;label&gt;Tempo &lt;input data-speed type="range" min="1" max="10" value="5"&gt;&lt;/label&gt;
      &lt;label&gt;Ziarno &lt;input data-seed type="number" min="1" max="9999" value="2026" style="width:5.5rem"&gt;&lt;/label&gt;
    &lt;/div&gt;
    &lt;div class="boarding-grid"&gt;&lt;/div&gt;
    &lt;div class="boarding-legend"&gt;
      &lt;span class="boarding-key"&gt;&lt;i class="boarding-dot" style="background:${COLORS.walking}"&gt;&lt;/i&gt; idzie&lt;/span&gt;
      &lt;span class="boarding-key"&gt;&lt;i class="boarding-dot" style="background:${COLORS.stowing}"&gt;&lt;/i&gt; odkłada bagaż&lt;/span&gt;
      &lt;span class="boarding-key"&gt;&lt;i class="boarding-dot" style="background:${COLORS.seated}"&gt;&lt;/i&gt; siedzi&lt;/span&gt;
    &lt;/div&gt;
  &lt;/div&gt;`;
  const grid = root.querySelector(".boarding-grid");
  const panels = new Map();
  for (const m of methods) {
    const panel = html`&lt;section class="boarding-panel"&gt;&lt;h3&gt;${m.label}&lt;/h3&gt;&lt;div class="boarding-status"&gt;&lt;/div&gt;&lt;svg viewBox="0 0 250 666" role="img" aria-label="Symulacja: ${m.label}"&gt;&lt;/svg&gt;&lt;/section&gt;`;
    grid.append(panel); panels.set(m.id, panel);
  }

  let sims, timer = null;
  function reset() {
    pause();
    const seed = +root.querySelector("[data-seed]").value || 2026;
    sims = methods.map((m,i) =&gt; makeSim(m.id, seed + 101 * i));
    render();
  }
  function start() {
    if (timer || sims.every(s =&gt; s.done)) return;
    const loop = () =&gt; {
      for (const s of sims) step(s);
      render();
      if (sims.every(s =&gt; s.done)) pause();
    };
    const speed = +root.querySelector("[data-speed]").value;
    timer = setInterval(loop, 310 - 27 * speed);
  }
  function pause() { if (timer) clearInterval(timer); timer = null; }

  function render() {
    for (const sim of sims) {
      const panel = panels.get(sim.method), svg = panel.querySelector("svg");
      const y = r =&gt; 625 - r * 24;
      let marks = `&lt;rect x="64" y="32" width="122" height="630" rx="55" fill="none" stroke="${COLORS.outline}" stroke-width="2"/&gt;`;
      marks += `&lt;rect x="116" y="42" width="18" height="590" fill="${COLORS.aisle}"/&gt;`;
      for (let r=0; r&lt;ROWS; ++r) {
        marks += `&lt;text x="51" y="${y(r)+5}" text-anchor="end" font-size="9" fill="${COLORS.text}"&gt;${r+1}&lt;/text&gt;`;
        for (let c=0; c&lt;6; ++c) {
          const x = 70 + c*16 + (c&gt;AISLE_AFTER ? 18 : 0);
          const fill = sim.seated.has(`${r}-${c}`) ? COLORS.seated : COLORS.empty;
          marks += `&lt;rect x="${x}" y="${y(r)-8}" width="12" height="16" rx="2" fill="${fill}"/&gt;`;
        }
      }
      for (const p of sim.active) {
        const cy = p.pos &lt; 0 ? 646 : y(p.pos);
        const fill = p.state === "stowing" ? COLORS.stowing : COLORS.walking;
        marks += `&lt;circle cx="125" cy="${cy}" r="6" fill="${fill}" stroke="white" stroke-width="1"&gt;&lt;title&gt;${p.id}&lt;/title&gt;&lt;/circle&gt;`;
      }
      svg.innerHTML = marks;
      const seated = sim.seated.size;
      panel.querySelector(".boarding-status").textContent = sim.done
        ? `Koniec: ${sim.time} jednostek czasu`
        : `czas ${sim.time} · siedzi ${seated}/144`;
    }
  }
  root.querySelector("[data-action=start]").onclick = start;
  root.querySelector("[data-action=pause]").onclick = pause;
  root.querySelector("[data-action=reset]").onclick = reset;
  root.querySelector("[data-speed]").onchange = () =&gt; { const wasRunning = !!timer; pause(); if (wasRunning) start(); };
  root.querySelector("[data-seed]").onchange = reset;
  invalidation.then(pause);
  reset();
  return root;
}
Czy potrafisz uzasadnić dlaczego metoda uporządkowana wypada słabiej niż losowa kolejność? Czy potrafisz uzasadnić, że metoda Steffena jest optymalna?

1.2 Półmaraton w Tokio
Kolejny przykład pochodzi z Tokio, gdzie w październiku 2024 roku odbył się Hakone Ekiden Yosenkai - półmaraton (bieg na 21.0975 km) kwalifikacyjny do wyścigu Hakone Ekiden (bieg sztafetowy). Oczywiście spodziewamy się, że znakomita większość zawodników uplasuje się w połowie stawki i kilka najszybszych lub najwolniejszych osób będzie odstawało odpowiednio na jej początku i końcu.

Okazuje się jednak, że dokładny rozkład biegaczy jest bardzo regularny. Zaobserwowana krzywa to funkcja dzwonowa, która jest równa \[\begin{equation*}
    \exp \left(-(x-\mu)^2/(2\sigma^2)\right)/\sqrt{2\pi\sigma^2}
\end{equation*}\] dla pewnych parametrów \(\sigma&gt;0\) oraz \(\mu \in \mathbb{R}\). W trakcie wykładu nauczymy się szukać tego typu regularności i zobaczymy dokładnie skąd bierze się zaobserwowany kształt. Parametry \(\mu\) oraz \(\sigma\) są odpowiednio odpowiedzialne za przesunięcie i kształt krzywej.


Pokaż kod
Plot = require("@observablehq/plot")









Pokaż kod
viewof normal_mu = Inputs.range([-4, 4], {
  value: 0,
  step: 0.1,
  label: "Dryf μ"
})

viewof normal_variance = Inputs.range([0.1, 4], {
  value: 1,
  step: 0.1,
  label: "Wariancja σ²"
})


















Pokaż kod
normal_density = {
  const sigma = Math.sqrt(normal_variance);

  return Array.from({length: 501}, (_, i) =&gt; {
    const x = -8 + (16 * i) / 500;

    const density =
      Math.exp(-((x - normal_mu) ** 2) / (2 * normal_variance)) /
      Math.sqrt(2 * Math.PI * normal_variance);

    return {x, density};
  });
}









Pokaż kod
Plot.plot({
  width: 800,
  height: 400,
  marginLeft: 55,
  marginBottom: 45,

  x: {
    domain: [-8, 8],
    label: "x",
    grid: true
  },

  y: {
    domain: [0, 1.3],
    label: "gęstość",
    grid: true
  },

  marks: [
    Plot.areaY(normal_density, {
      x: "x",
      y: "density",
      fill: "#3b82f6",
      fillOpacity: 0.2
    }),

    Plot.lineY(normal_density, {
      x: "x",
      y: "density",
      stroke: "#2563eb",
      strokeWidth: 3
    }),

    Plot.ruleX([normal_mu], {
      stroke: "#dc2626",
      strokeWidth: 2,
      strokeDasharray: "5,5"
    }),

    Plot.text(
      [{
        x: normal_mu,
        y: 1.22,
        label:
          `μ = ${normal_mu.toFixed(1)},  σ² = ${normal_variance.toFixed(1)}`
      }],
      {
        x: "x",
        y: "y",
        text: "label",
        dx: normal_mu &gt; 2.5 ? -8 : 8,
        textAnchor: normal_mu &gt; 2.5 ? "end" : "start",
        fill: "#dc2626"
      }
    )
  ]
})

1.3 IMDb
Rozważmy filmy nakręcone w latach \(2000-2025\), które obejrzało co najmniej \(1000\) osób. Każdy film ma swoją ocenę w serwisie IMDb. Co zobaczymy, gdy zamiast pojedynczych tytułów przyjrzymy się tysiącom filmów jednocześnie? Jedna obserwacja to jeden film i jego ocena w IMDb.


Pokaż kod
imdbRows = FileAttachment("CSV/imdb_filmy_2000_2025_min1000.csv").csv({typed: true})

imdbRatings = imdbRows.map(d =&gt; d.averageRating)
  .filter(x =&gt; Number.isFinite(x) && x &gt;= 1 && x &lt;= 10)

// Ustalona losowa kolejność: zwiększenie próby dodaje kolejne filmy.
imdbOrder = {
  const a = imdbRatings.slice();
  let seed = 20261006;
  for (let i = a.length - 1; i &gt; 0; --i) {
    seed = (Math.imul(1664525, seed) + 1013904223) &gt;&gt;&gt; 0;
    const j = Math.floor((seed / 4294967296) * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}

viewof imdbN = Inputs.range([50, imdbOrder.length], {
  value: imdbOrder.length, step: 1, label: "Liczba filmów"
})

viewof imdbShowNormal = Inputs.toggle({
  value: true, label: "Pokaż krzywą normalną"
})

imdbSample = imdbOrder.slice(0, imdbN)

imdbStats = {
  const n = imdbSample.length;
  const mean = imdbSample.reduce((s, x) =&gt; s + x, 0) / n;
  const sd = Math.sqrt(imdbSample.reduce((s, x) =&gt; s + (x - mean) ** 2, 0) / n);
  return {n, mean, sd};
}

// Każdy przedział obejmuje dwie oceny, np. 6,0 i 6,1.
imdbBins = {
  const bins = Array.from({length: 46}, (_, i) =&gt; ({
    left: 0.95 + 0.2 * i, right: 1.15 + 0.2 * i, count: 0
  }));
  for (const x of imdbSample) {
    bins[Math.floor((Math.round(x * 10) - 10) / 2)].count++;
  }
  return bins;
}

// Gęstość normalna przeskalowana do liczebności słupków.
imdbCurve = Array.from({length: 601}, (_, i) =&gt; {
  const x = 0.8 + 9.4 * i / 600;
  const {n, mean, sd} = imdbStats;
  const y = n * 0.2 / (sd * Math.sqrt(2 * Math.PI))
    * Math.exp(-0.5 * ((x - mean) / sd) ** 2);
  return {x, y};
})

md`**Liczba filmów:** ${imdbStats.n.toLocaleString("pl-PL")} ·
**Średnia:** ${imdbStats.mean.toLocaleString("pl-PL", {minimumFractionDigits: 2, maximumFractionDigits: 2})} ·
**Odchylenie standardowe:** ${imdbStats.sd.toLocaleString("pl-PL", {minimumFractionDigits: 2, maximumFractionDigits: 2})}`








































































Pokaż kod
Plot.plot({
  width: Math.min(width, 900), height: 420,
  marginLeft: 65, marginBottom: 50,
  style: {background: "transparent", color: "currentColor", fontSize: "13px"},
  x: {domain: [0.8, 10.2], label: "Ocena IMDb", ticks: 10},
  y: {
    label: "Liczba filmów", grid: true, zero: true,
    tickFormat: x =&gt; x.toLocaleString("pl-PL", {maximumFractionDigits: 0})
  },
  marks: [
    Plot.rectY(imdbBins, {
      x1: "left", x2: "right", y: "count", fill: "#5c94b5",
      insetLeft: 0.5, insetRight: 0.5,
      title: d =&gt; `Oceny: ${(d.left + 0.05).toFixed(1)} i ${(d.right - 0.05).toFixed(1)}\nLiczba filmów: ${d.count}`
    }),
    ...(imdbShowNormal ? [Plot.line(imdbCurve, {
      x: "x", y: "y", stroke: "#d06844", strokeWidth: 3
    })] : []),
    Plot.ruleY([0])
  ]
})









Niebieskie słupki przedstawiają rzeczywiste oceny filmów. Pomarańczowa linia to krzywa normalna o tej samej średniej i odchyleniu standardowym co wybrana próba.
Ostateczny histogram przypomina dzwon, ale ma dłuższy lewy ogon. Krzywa normalna jest więc przybliżeniem. Zwiększanie liczby filmów pozwala lepiej zobaczyć rozkład ocen — nie zmienia go automatycznie w rozkład normalny.

1.4 Opóźnienia lotów
Przyjrzyjmy się lotom z nowojorskich lotnisk w 2013 roku. Możemy porównać odchylenia przylotów od rozkładu albo czasy spędzone w powietrzu na jednej trasie: JFK–Los Angeles.


Pokaż kod
flightRows = FileAttachment("CSV/loty_nyc_2013.csv").csv({typed: true})

viewof flightMode = Inputs.select([
  "Czas lotu JFK–Los Angeles",
  "Opóźnienia wszystkich lotów",
  "Przyloty po punktualnym lub wcześniejszym wylocie"
], {label: "Wybierz dane"})

viewof flightShowNormal = Inputs.toggle({
  value: true, label: "Pokaż krzywą normalną"
})

flightConfig = flightMode === "Czas lotu JFK–Los Angeles"
  ? {column: "air_time", label: "Czas spędzony w powietrzu (min)"}
  : {column: "arr_delay", label: "Odchylenie przylotu od rozkładu (min)"}

flightValues = {
  let rows = flightRows;
  if (flightMode === "Czas lotu JFK–Los Angeles") {
    rows = rows.filter(d =&gt; d.origin === "JFK" && d.dest === "LAX");
  } else if (flightMode === "Przyloty po punktualnym lub wcześniejszym wylocie") {
    rows = rows.filter(d =&gt; Number.isFinite(d.dep_delay) && d.dep_delay &lt;= 0);
  }
  return rows.map(d =&gt; d[flightConfig.column]).filter(Number.isFinite);
}

// Stała losowa kolejność: zwiększenie próby dodaje kolejne loty.
flightOrder = {
  const a = flightValues.slice();
  let seed = 20261006;
  for (let i = a.length - 1; i &gt; 0; --i) {
    seed = (Math.imul(1664525, seed) + 1013904223) &gt;&gt;&gt; 0;
    const j = Math.floor((seed / 4294967296) * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}

viewof flightN = Inputs.range([50, flightOrder.length], {
  value: flightOrder.length, step: 1, label: "Liczba lotów"
})

flightSample = flightOrder.slice(0, flightN)

flightStats = {
  const n = flightSample.length;
  const mean = flightSample.reduce((s, x) =&gt; s + x, 0) / n;
  const sd = Math.sqrt(flightSample.reduce((s, x) =&gt; s + (x - mean) ** 2, 0) / n);
  return {n, mean, sd};
}

// Oś obejmuje całą wybraną grupę, także przy małej próbie.
flightBounds = {
  let min = Infinity, max = -Infinity;
  for (const x of flightValues) {
    min = Math.min(min, x);
    max = Math.max(max, x);
  }
  return {
    left: 5 * Math.floor(min / 5) - 2.5,
    right: 5 * Math.ceil(max / 5) + 2.5,
    step: 5
  };
}

flightBins = {
  const {left, right, step} = flightBounds;
  const bins = Array.from({length: Math.round((right - left) / step)}, (_, i) =&gt; ({
    left: left + i * step,
    right: left + (i + 1) * step,
    count: 0
  }));
  for (const x of flightSample) {
    bins[Math.floor((x - left) / step)].count++;
  }
  return bins.map(d =&gt; ({...d, percent: 100 * d.count / flightStats.n}));
}

flightCurve = Array.from({length: 1001}, (_, i) =&gt; {
  const {left, right, step} = flightBounds;
  const {mean, sd} = flightStats;
  const x = left + (right - left) * i / 1000;
  const y = 100 * step / (sd * Math.sqrt(2 * Math.PI))
    * Math.exp(-0.5 * ((x - mean) / sd) ** 2);
  return {x, y};
})

