galton = {
  const N = 12;
  const W = 720;
  const H = 650;

  const top = 55;
  const rowGap = 35;
  const pegGap = 38;
  const center = W / 2;

  const binTop = top + N * rowGap + 25;
  const binHeight = 125;

  const root = html`&lt;div class="galton-root"&gt;
